<script>document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const i=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(i.value);b.textContent='Copied';setTimeout(()=>b.textContent=b.dataset.copy==='mainLink'?'Copy link':'Copy',1500)}catch(e){i.select();document.execCommand('copy');b.textContent='Copied'}});document.querySelectorAll('[data-share]').forEach(b=>b.onclick=async()=>{const i=document.getElementById(b.dataset.share);if(navigator.share){await navigator.share({title:'Join DogoFlow',text:'Join DogoFlow through my referral link.',url:i.value})}else{await navigator.clipboard.writeText(i.value);document.getElementById('msg').textContent='Link copied. You can share it anywhere.'}});</script><?php aff_foot();
